import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize font at module level
const { fontFamily: interFamily } = loadInter();

// Single inline schema


export type FolderAnimationProps = Record<string, any>;

// Reusable Texture Component
const TextureOverlay: React.FC<{ opacity?: number }> = ({ opacity = 0.25 }) => (
  <svg
    style={{
      position: "absolute",
      inset: 0,
      width: "100%",
      height: "100%",
      opacity,
      mixBlendMode: "overlay",
      pointerEvents: "none",
    }}
  >
    <filter id="grain">
      <feTurbulence
        type="fractalNoise"
        baseFrequency="0.8"
        numOctaves="3"
        stitchTiles="stitch"
      />
    </filter>
    <rect width="100%" height="100%" filter="url(#grain)" />
  </svg>
);

const FolderAnimation: React.FC<FolderAnimationProps> = ({
  backgroundColorCenter = "#FFFFFF",
  backgroundColorEdge = "#E0E0E0",
  transparentBackground = false,
  durationInSeconds = 5,
  folder1Line1 = "secret",
  folder1Line2 = "resources.",
  folder1Badge = "Vol.01",
  folder2Line1 = "secret",
  folder2Line2 = "tools.",
  folder2Badge = "Vol.01",
  folderFrontColor = "#C5C5C5",
  folderBackColor = "#B0B0B0",
  folderShadowColor = "#828282",
  paperOrangeColor = "#EB5B25",
  paperDarkColor = "#333333",
  paperYellowColor = "#F5B82E",
  textColor = "#222222",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const backgroundStyle = transparentBackground
    ? "transparent"
    : `radial-gradient(circle, ${backgroundColorCenter} 0%, ${backgroundColorEdge} 100%)`;

  const foldersData = [
    { line1: folder1Line1, line2: folder1Line2, badge: folder1Badge },
    { line1: folder2Line1, line2: folder2Line2, badge: folder2Badge },
  ];

  return (
    <AbsoluteFill
      style={{
        background: backgroundStyle,
        display: "flex",
        flexDirection: "row",
        justifyContent: "center",
        alignItems: "center",
        gap: 200, // Space between the two folders
      }}
    >
      {foldersData.map((folder, index) => {
        // Animation Timings per folder
        const delay = index * 20;

        // 1. Folder Entrance (Scale & Translate Up)
        const entranceSpring = spring({
          frame: frame - delay,
          fps,
          config: { damping: 12, mass: 1 },
        });
        const folderScale = interpolate(entranceSpring, [0, 1], [0.8, 1]);
        const folderY = interpolate(entranceSpring, [0, 1], [150, 0]);
        const folderOpacity = interpolate(entranceSpring, [0, 0.5], [0, 1]);

        // 2. Papers Sliding Up
        const paperSpring = spring({
          frame: frame - delay - 15,
          fps,
          config: { damping: 14, mass: 0.8 },
        });
        const paperOrangeY = interpolate(paperSpring, [0, 1], [120, 0]);
        const paperDarkY = interpolate(paperSpring, [0, 1], [120, 15]);
        const paperYellowY = interpolate(paperSpring, [0, 1], [120, 30]);

        return (
          <div
            key={index}
            style={{
              position: "relative",
              width: 480,
              height: 360,
              transform: `scale(${folderScale}) translateY(${folderY}px)`,
              opacity: folderOpacity,
            }}
          >
            {/* Back Tab */}
            <div
              style={{
                position: "absolute",
                top: -25,
                left: 30,
                width: 200,
                height: 50,
                backgroundColor: folderBackColor,
                borderRadius: "20px 20px 0 0",
                overflow: "hidden", // For noise
              }}
            >
              <TextureOverlay opacity={0.15} />
            </div>

            {/* Papers Container (Masked by bottom edge, sticking out top) */}
            <div
              style={{
                position: "absolute",
                top: -100,
                left: 60,
                width: 360,
                height: 250,
              }}
            >
              {/* Paper 1 (Orange - Back) */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  backgroundColor: paperOrangeColor,
                  borderRadius: "8px 8px 0 0",
                  transform: `translateY(${paperOrangeY}px) rotate(-3deg)`,
                  transformOrigin: "bottom left",
                }}
              />
              {/* Paper 2 (Dark - Middle) */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 5,
                  width: "95%",
                  height: "100%",
                  backgroundColor: paperDarkColor,
                  borderRadius: "8px 8px 0 0",
                  transform: `translateY(${paperDarkY}px) rotate(-0.5deg)`,
                  transformOrigin: "bottom left",
                }}
              />
              {/* Paper 3 (Yellow - Front) */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 10,
                  width: "90%",
                  height: "100%",
                  backgroundColor: paperYellowColor,
                  borderRadius: "8px 8px 0 0",
                  transform: `translateY(${paperYellowY}px) rotate(2deg)`,
                  transformOrigin: "bottom left",
                }}
              />
            </div>

            {/* Folder Front Shadow (Extrusion effect) */}
            <div
              style={{
                position: "absolute",
                top: 14,
                left: 14,
                width: "100%",
                height: "100%",
                backgroundColor: folderShadowColor,
                borderRadius: 24,
              }}
            />

            {/* Folder Front Main Body */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                backgroundColor: folderFrontColor,
                borderRadius: 24,
                overflow: "hidden", // Crucial for texture to not bleed
              }}
            >
              <TextureOverlay opacity={0.25} />

              {/* Typography Group */}
              <div
                style={{
                  position: "absolute",
                  bottom: 35,
                  left: 45,
                  display: "flex",
                  flexDirection: "column",
                  fontFamily: interFamily,
                }}
              >
                <span
                  style={{
                    color: textColor,
                    fontSize: 56,
                    fontWeight: 800,
                    lineHeight: 0.95,
                    letterSpacing: "-0.04em",
                  }}
                >
                  {folder.line1}
                </span>
                <span
                  style={{
                    color: textColor,
                    fontSize: 56,
                    fontWeight: 800,
                    lineHeight: 0.95,
                    letterSpacing: "-0.04em",
                  }}
                >
                  {folder.line2}
                </span>
              </div>

              {/* Badge */}
              <div
                style={{
                  position: "absolute",
                  top: 25,
                  right: 25,
                  backgroundColor: "rgba(255,255,255,0.4)",
                  padding: "6px 18px",
                  borderRadius: 20,
                  fontFamily: interFamily,
                  fontSize: 20,
                  fontWeight: 500,
                  color: textColor,
                  letterSpacing: "-0.02em",
                }}
              >
                {folder.badge}
              </div>
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default FolderAnimation;